print('total rows', len(targets))

def solvable(nums, target):
    # all binary tree expressions over the multiset of numbers
    def rec(vals):
        if len(vals) == 1:
            return Fraction(vals[0]) == Fraction(target)
        for i in range(len(vals)):
            for j in range(i+1, len(vals)):
                rest = [vals[k] for k in range(len(vals)) if k != i and k != j]
                a, b = vals[i], vals[j]
                cands = [a+b, a-b, b-a, a*b]
                if b != 0: cands.append(a/b)
                if a != 0: cands.append(b/a)
                for c in cands:
                    if rec(rest + [c]):
                        return True
        return False
